package dev.hrutvik.billing.usage;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.hrutvik.billing.catalog.*; import dev.hrutvik.billing.outbox.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class UsageEventServiceTest {
 UsageEventRepository events=mock(UsageEventRepository.class); MeterRepository meters=mock(MeterRepository.class); SubscriptionAccessStore subscriptions=mock(SubscriptionAccessStore.class); OutboxEventRepository outbox=mock(OutboxEventRepository.class); UsageFingerprint fp=new UsageFingerprint(); Instant now=Instant.parse("2026-11-01T10:00:00Z"); UUID subscription=UUID.randomUUID(); UsageEventService service=new UsageEventService(events,meters,subscriptions,outbox,fp,new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC),Duration.ofDays(7),Duration.ofMinutes(5));
 UsageEventRequest request(){return new UsageEventRequest("evt-1",subscription,"api_calls",new BigDecimal("12"),now.minusSeconds(10),Map.of("region","in"));}
 @Test void persistsLedgerAndOutboxAtomically(){when(events.findByTenantIdAndExternalEventId("tenant-a","evt-1")).thenReturn(Optional.empty());when(subscriptions.isActiveForTenant("tenant-a",subscription)).thenReturn(true);when(meters.findByTenantIdAndMeterKeyAndActiveTrue("tenant-a","api_calls")).thenReturn(Optional.of(mock(Meter.class)));var result=service.ingest("tenant-a",request());assertThat(result.replayed()).isFalse();assertThat(result.subscriptionId()).isEqualTo(subscription);verify(events).save(any());verify(outbox).save(any());}
 @Test void exactRetryReturnsOriginalWithoutWriting(){var r=request();var prior=new UsageEvent(UUID.randomUUID(),"tenant-a",subscription,"evt-1",fp.create(r),"api_calls",r.quantity(),r.occurredAt(),now,"{}");when(events.findByTenantIdAndExternalEventId("tenant-a","evt-1")).thenReturn(Optional.of(prior));assertThat(service.ingest("tenant-a",r).replayed()).isTrue();verifyNoInteractions(meters,subscriptions,outbox);}
 @Test void mismatchedRetryIsConflict(){var r=request();var prior=new UsageEvent(UUID.randomUUID(),"tenant-a",subscription,"evt-1","different","api_calls",r.quantity(),r.occurredAt(),now,"{}");when(events.findByTenantIdAndExternalEventId("tenant-a","evt-1")).thenReturn(Optional.of(prior));assertThatThrownBy(()->service.ingest("tenant-a",r)).isInstanceOf(IdempotencyConflict.class);}
 @Test void rejectsEventsOutsideWindow(){when(events.findByTenantIdAndExternalEventId(any(),any())).thenReturn(Optional.empty());var old=new UsageEventRequest("evt-1",subscription,"api_calls",BigDecimal.ONE,now.minus(Duration.ofDays(8)),Map.of());assertThatThrownBy(()->service.ingest("tenant-a",old)).isInstanceOf(EventOutsideWindow.class);}
 @Test void rejectsCrossTenantSubscription(){when(events.findByTenantIdAndExternalEventId(any(),any())).thenReturn(Optional.empty());when(subscriptions.isActiveForTenant("tenant-a",subscription)).thenReturn(false);assertThatThrownBy(()->service.ingest("tenant-a",request())).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("subscription");verifyNoInteractions(meters,outbox);}
}
